'use strict';
/* Guide QA: geometry/input frozen against d44c817; guided/free play use current controller. No browser or publish.
 * Production controller/geometry/helper + full JSDOM integration and real RAF.
 * jsdom 26.1.0 is a dev-only dependency declared in qa/package.json. */
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {fixture,source,baselineRef}=require('./lesson-harness.cjs');
const app=source('app.js'),baseline=source('app.js',true),results=[],evidence={stateFrames:0,svgComparisons:0,phases:new Set()};
function test(name,fn){try{fn();results.push({name,ok:true});console.log('PASS '+name);}catch(error){results.push({name,ok:false,error:error.stack});console.error('FAIL '+name+'\n'+error.stack);}}
function read(f){const before=f.snapshot(),out=f.read();assert.deepEqual(f.snapshot(),before,'read cannot mutate mechanics');assert.equal(out.phase,f.s.phase);assert.equal(out.completed,false);assert(out.title&&out.text&&out.look&&out.label);assert(!/undefined|NaN|Infinity/.test(JSON.stringify(out)));assert.equal(out.choices.length,5);assert.equal(out.busy,(f.s.phase!=='idle'&&f.s.phase!=='prize')||f.s.aiming);assert(f.s.won.length<=4&&f.s.tries>=f.s.won.length);assert.equal(f.s.stock.length+f.s.won.length,4);evidence.phases.add(f.s.phase);return out;}
const atPhase=phase=>{const f=fixture();f.lesson(true);f.choice('aim-0');if(phase==='aim')return f;f.finish();if(phase==='idle')return f;f.next();f.until(phase==='return'||phase==='collect'?'prize':phase);if(phase==='collect'||phase==='return'){f.next();if(phase==='return')f.until('return');}return f;};
const snapshotEqual=(a,b,label,draw=false)=>{assert.deepEqual(a.snapshot(),b.snapshot(),label);assert.equal(a.pending,b.pending,label+' active callbacks');evidence.stateFrames++;if(draw){for(const[yaw,pitch]of[[38,23],[135,35],[225,15],[315,65]]){assert.equal(a.render(yaw,pitch),b.render(yaw,pitch),label+' exact SVG '+yaw+'/'+pitch);evidence.svgComparisons++;}}};
test('Geometry, depth sort, input and original observer are byte-identical to baseline',()=>{
 const before=s=>s.slice(0,s.indexOf('function restock'));assert.equal(before(app),before(baseline));
 const after=s=>s.slice(s.indexOf('const ui=mountFigure'),s.indexOf('clawObservation=window.MuseumObservation')).replaceAll('https://paper-mechanical-museum.chuangcius.chatgpt.site','../../object-collection/dist/');assert.equal(after(app),after(baseline));
 assert.equal(source('index.html').replace(/\?v=[\w-]+/g,''),source('index.html',true).replace(/\?v=[\w-]+/g,''));
 assert.equal(source('shared-shell.css'),source('shared-shell.css',true));
 const added=app.slice(app.indexOf('let clawLessonEnabled=false;'));assert(!/setTimeout|setInterval|requestAnimationFrame|ui\.animate/.test(added),'no new clock');
});
test('Default free play is unchanged, lesson entry is opt-in and entry/exit never selects a target',()=>{
 const f=fixture(),before=f.snapshot();assert.equal(f.read().enabled,false);for(let i=0;i<10;i++){f.next();f.choice('aim-0');f.choice('restock');}assert.deepEqual(f.snapshot(),before);
 for(let i=0;i<20;i++){f.lesson(true);read(f);assert.deepEqual(f.snapshot(),before);f.lesson(false);assert.deepEqual(f.snapshot(),before);}assert.equal(f.pending,0);f.close();
});
test('All four guided wins, miss, restock and full-sequence exact state/SVG match current free play',()=>{
 const a=fixture(),b=fixture();a.lesson(true);snapshotEqual(a,b,'initial',true);let frames=0;
 const settle=label=>{while(a.pending||b.pending){a.frame();b.frame();frames++;read(a);snapshotEqual(a,b,label+' '+frames,frames%47===0);if(frames>2500)throw Error('Sequence did not settle');}snapshotEqual(a,b,label+' rest',true);};
 for(let i=0;i<4;i++){a.choice('aim-'+i);b.action('aim',i);settle('aim '+i);a.next();b.action('drop');settle('grab '+i);assert.equal(a.s.phase,'prize');a.next();b.action('collect');settle('collect '+i);assert.equal(a.s.won.length,i+1);}
 assert.equal(a.read().label,'再玩一轮');a.next();b.action('drop');settle('restock');assert.equal(a.s.tries,0);assert.equal(a.s.won.length,0);
 for(const f of[a,b]){f.s.x=31;f.s.y=37;}a.next();b.action('drop');settle('miss');assert.equal(a.s.result,'miss');assert.match(a.read().text,/不会替你改选/);assert.equal(a.s.won.length,0);a.close();b.close();
});
test('Every real grab and collection phase is read live and repeated/invalid card actions are inert',()=>{
 for(const phase of['down','close','up','travel','release','fall','eject','prize','collect','return']){
  const f=atPhase(phase),out=read(f),before=f.snapshot();assert.equal(out.choices.at(-1).disabled,true);assert.match(out.choices.at(-1).label,/完成并领取/);
  for(let n=0;n<12;n++){f.choice('restock');f.choice('aim-2');f.choice('aim-999');f.choice('__proto__');if(phase!=='prize')f.next();}assert.deepEqual(f.snapshot(),before,phase+' invalid input changed game');
  f.lesson(false);f.next();f.choice('restock');assert.deepEqual(f.snapshot(),before,phase+' closed guide changed game');f.finish();assert.equal(f.s.tries,1);assert(f.s.won.length<=1);f.close();
 }
});
test('No fabricated grip physics: original strict centre-distance threshold controls success and miss',()=>{
 for(const distance of[4.499,4.5,5]){const f=fixture();f.lesson(true);f.s.x=42+distance;f.s.y=57;f.next();f.until('up');assert.equal(f.s.got,distance<4.5?0:null);assert.match(f.read().text,distance<4.5?/夹中的娃娃/:/空载/);f.finish();assert.equal(f.s.phase,distance<4.5?'prize':'idle');assert.equal(f.s.tries,1);f.close();}
});
test('Exiting at every phase preserves exact aim, motion, timing and inventory; the same cycle continues',()=>{
 for(const phase of['aim','down','close','up','travel','release','fall','eject','prize','collect','return']){const f=atPhase(phase),before=f.snapshot(),pending=f.pending;for(let i=0;i<15;i++)f.lesson(false);assert.deepEqual(f.snapshot(),before,phase+' exit altered state');assert.equal(f.pending,pending);f.finish();if(phase==='aim'){assert.equal(f.s.target,0);assert.equal(f.s.tries,0);}else if(phase==='collect'||phase==='return'){assert.equal(f.s.won.length,1);assert.equal(f.s.phase,'idle');}else{assert.equal(f.s.phase,'prize');assert.equal(f.s.won.length,0);}f.close();}
});
test('Original restock guard remains during busy stages; idle restock cancels automatic aim cleanly',()=>{
 for(const phase of['down','close','up','travel','release','fall','eject','prize','collect','return']){const f=atPhase(phase),before=f.snapshot();f.action('restock');assert.deepEqual(f.snapshot(),before);assert.match(f.messages.at(-1),/完成并领取/);f.finish();f.close();}
 const f=atPhase('aim');f.tick(.2);f.choice('restock');const position=[f.s.x,f.s.y];assert.equal(f.s.phase,'idle');assert.equal(f.s.aiming,false);assert.equal(f.s.target,null);assert.equal(f.s.tries,0);f.finish();assert.deepEqual([f.s.x,f.s.y],position);assert.equal(f.pending,0);f.choice('aim-3');f.finish();f.next();f.finish();assert.equal(f.s.got,3);assert.equal(f.s.tries,1);f.close();
});
test('Live card geometry stays byte-identical across all yaw/pitch views and partial mechanical phases',()=>{
 const a=atPhase('down'),b=fixture({baseline:true});for(const phase of['down','close','up','travel','release','fall','eject','prize','collect','return']){if(phase==='collect')a.next();a.until(phase);a.tick(.12);Object.assign(b.s,a.snapshot());for(const yaw of[0,45,90,135,180,225,270,315])for(const pitch of[6,35,78]){assert.equal(a.render(yaw,pitch),b.render(yaw,pitch),phase+' '+yaw+'/'+pitch);evidence.svgComparisons++;}read(a);}a.finish();a.close();b.close();
});
function integrated(coarse=false){const f=fixture({full:true,coarse});f.guide=f.d.querySelector('.claw-guide');f.panel=f.ui.observation.panel;f.dock=f.d.querySelector('.play-dock');f.primary=f.d.getElementById('btns');f.pad=f.d.querySelector('.gamepad');f.go=f.guide.querySelector('.mechanism-lesson-go');f.exit=f.guide.querySelector('.mechanism-lesson-exit');f.choose=id=>f.guide.querySelector('[data-choice="'+id+'"]').click();return f;}
function sync(f){const live=read(f);f.ui.observation.update();assert.equal(f.guide.querySelector('.mechanism-lesson-title').textContent,'当前 · '+live.title);assert.equal(f.guide.querySelector('.mechanism-lesson-reason').textContent,live.text);assert.equal(f.go.getAttribute('aria-disabled'),String(live.busy));assert.equal(f.guide.querySelector('.mechanism-lesson-hold').hidden,true);assert.equal(f.guide.querySelectorAll('[aria-current="step"]').length,1);for(const dot of f.guide.querySelectorAll('.mechanism-lesson-route span'))assert.equal(dot.dataset.done,'false');return live;}
test('Production helper folds/restores the same action nodes, leaves direct pad reachable, and preserves focus',()=>{
 const f=integrated(),before=f.snapshot(),home=f.guide.parentElement,buttons=[...f.primary.children];assert.equal(f.panel.open,false);assert.equal(f.guide.open,false);assert.equal(f.panel.querySelector('summary').textContent,'看原理');assert.equal(f.pending,0);f.open();sync(f);assert.deepEqual(f.snapshot(),before);assert.equal(f.guide.parentElement,f.dock);assert.equal(f.primary.parentElement.className,'lesson-free-controls claw-free-controls');assert.equal(f.primary.parentElement.open,false);assert.equal(f.pad.parentElement,f.dock);assert.equal(f.d.activeElement,f.guide.querySelector('summary'));assert.equal(f.d.querySelectorAll('#btns').length,1);assert.equal(home.querySelector('.observation-live').hidden,true);assert.equal(f.pending,0);
 f.go.focus();f.ui.render();assert.equal(f.d.activeElement,f.go);f.exit.click();assert.equal(f.primary.parentElement,f.dock);assert.equal(f.guide.parentElement,home);assert.deepEqual([...f.primary.children],buttons);assert.equal(f.d.activeElement,f.guide.querySelector('summary'));assert.equal(home.querySelector('.observation-live').hidden,false);assert.deepEqual(f.snapshot(),before);assert.equal(f.pending,0);f.close();
});
test('Production card choices use real aim/drop/collect; focus survives redraw and repeated activation never duplicates',()=>{
 const f=integrated();f.open();const target=f.guide.querySelector('[data-choice="aim-0"]');target.focus();target.click();assert.equal(f.s.target,0);assert.notEqual(f.d.activeElement,target,'disabled target focus moves to an enabled choice');f.go.click();assert.equal(f.s.tries,0,'cannot drop before aim settles');f.finish();sync(f);f.go.focus();f.go.click();for(let i=0;i<12;i++)f.go.click();assert.equal(f.s.tries,1);f.tick(.2);assert.equal(f.d.activeElement,f.go);sync(f);f.exit.click();const before=f.snapshot();assert.equal(f.primary.parentElement,f.dock);assert.equal(f.s.phase,'down');f.frame();assert(f.s.z<before.z);f.finish();assert.equal(f.s.phase,'prize');f.open();sync(f);f.go.click();for(let i=0;i<12;i++)f.go.click();f.finish();assert.equal(f.s.phase,'idle');assert.equal(f.s.won.length,1);assert.equal(f.s.tries,1);sync(f);assert.equal(f.pending,0);f.close();
});
test('Outer close/reopen joins current action; hidden page freezes real RAF and resumes without duplicate prizes',()=>{
 const f=integrated(true);f.open();f.choose('aim-2');f.finish();f.go.click();f.tick(.25);const before=f.snapshot();f.d.hidden=true;f.d.dispatchEvent(new f.dom.window.Event('visibilitychange'));assert.equal(f.pending,0);const parked=f.snapshot();assert.equal(parked.pressedAct,null,'existing hidden-tab handling clears press feedback');assert.deepEqual({...parked,pressedAct:null},{...before,pressedAct:null});f.tick(10);assert.deepEqual(f.snapshot(),parked);f.d.hidden=false;f.d.dispatchEvent(new f.dom.window.Event('visibilitychange'));f.frame();assert(f.s.z<before.z);f.toggle(f.panel,false);assert.equal(f.guide.open,false);assert.equal(f.read().enabled,false);assert.equal(f.primary.parentElement,f.dock);f.open();assert.equal(f.read().index,1);f.finish();assert.equal(f.s.phase,'prize');assert.equal(f.s.tries,1);f.go.click();f.finish();assert.equal(f.s.won.length,1);assert.equal(f.pending,0);f.close();
});
test('Direct hold-to-move/keyboard input remains active when guide is open; controls cancel without drift',()=>{
 const {create}=require('./input-harness.cjs');for(const cancel of['pointerup','pointercancel','lostpointercapture','blur','hidden','focus']){const f=create();f.run(app.slice(app.indexOf('const phaseLabels='),app.indexOf('const tactileRender=')));f.run(app.slice(app.indexOf('function readClawObservation(){'),app.indexOf('clawObservation=window.MuseumObservation')));f.run(app.slice(app.indexOf('let clawLessonEnabled=false;'),app.indexOf('const clawLesson=')));f.run('function updateExtrasOverflow(){};toggleClawLesson(true)');const b=f.button('right');b.emit('pointerdown',{pointerId:7});f.advance(160);const moving=[f.st.x,f.st.y];if(cancel==='blur')f.globals.emit('blur');else if(cancel==='hidden'){f.doc.hidden=true;f.doc.emit('visibilitychange');}else if(cancel==='focus'){b.emit('pointerup',{pointerId:7});f.svg.focus();f.svg.emit('keydown',{key:'ArrowRight'});f.buttons.vreset.focus();}else b.emit(cancel,{pointerId:7});const stop=[f.st.x,f.st.y];f.advance(350);assert.deepEqual([f.st.x,f.st.y],stop,cancel+' does not drift');assert.equal(f.run('held'),null);assert.equal(f.st.tries,0);assert.notDeepEqual(moving,[32,36]);}
});
test('Candidate local resource hashes, scripts and idle no-timer contract are verified',()=>{
 const index=source('index.html');for(const [,file,hash]of index.matchAll(/(?:src|href)="([^"?]+)\?v=([a-f0-9]+)"/g))assert.equal(crypto.createHash('sha256').update(source(file)).digest('hex').slice(0,12),hash,file+' resource hash');
 const f=integrated();f.open();const before=f.snapshot(),pending=f.pending,timers=f.timers;f.tick(20);assert.deepEqual(f.snapshot(),before);assert.equal(f.pending,pending);assert.equal(pending,0);assert.equal(f.timers,timers);f.ui.observation.dispose();assert.equal(f.primary.parentElement,f.dock);assert.equal(f.d.querySelector('.claw-guide'),null);assert.equal(f.pending,0);f.close();
});
const report={baselineRef,scope:'Optional claw live principle card; current guided/free controller equivalence, frozen geometry/depth/input; timing revision covered by audit-claw-time.cjs',browser:false,limits:'JSDOM + production source/RAF, not a layout, browser-native disclosure, touch or screen-reader test. Busy reset retains baseline refusal; only idle aim can be cancelled by existing restock.',stateFrames:evidence.stateFrames,svgComparisons:evidence.svgComparisons,phases:[...evidence.phases],results};
fs.writeFileSync(path.join(__dirname,'claw-lesson-results.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({groups:results.length,passed:results.filter(r=>r.ok).length,failed:results.filter(r=>!r.ok).length,stateFrames:report.stateFrames,svgComparisons:report.svgComparisons}));if(results.some(r=>!r.ok))process.exitCode=1;
